findings.evidence:
modifier poolManagerOnly() {
    _; // This is a no-op
}

findings.remediation:
The `poolManagerOnly` modifier must be implemented to verify that `msg.sender` is the official Uniswap v4 PoolManager contract. This typically involves storing the PoolManager address in a state variable and checking against it.

solidity
contract CryptoUPIHook is BaseHook, Ownable {
    // ...
    address public immutable poolManager;

    constructor(address _poolManager) {
        require(_poolManager != address(0), "Hook: Zero address");
        poolManager = _poolManager;
    }

    modifier poolManagerOnly() {
        require(msg.sender == poolManager, "Hook: Not PoolManager");
        _;
    }
    // ...
}

